// Load fake-graph.hdf5, exported by `aida-data export fake-graph`.
// Generated by aida-data 0.0.0 for HighFive 3.x (H5Easy), tested with HighFive 3.3.0.
// It loads the objects of the file it was generated from; each comment gives the shape and dtype.
//
// Build: h5c++ -std=c++17 -I/path/to/highfive/include load.cpp -o load
// or with CMake:
//   find_package(HighFive REQUIRED)
//   target_link_libraries(load HighFive::HighFive)
// HighFive comes from a package manager (apt install libhighfive-dev,
// conda install highfive, vcpkg install highfive) or a git submodule.
// With HighFive 2.x the CMake target is `HighFive` and DataSet::read_raw(T*)
// is DataSet::read(T*).
#include <highfive/H5Easy.hpp>

#include <cstdint>
#include <iostream>
#include <string>
#include <vector>

int main() {
    H5Easy::File file("fake-graph.hdf5", H5Easy::File::ReadOnly);

    // (9,) int64, CSR offsets, one per node plus one: the neighbors of node v are
    // neighbors[offsets[v]] to neighbors[offsets[v + 1] - 1].
    auto offsets = H5Easy::load<std::vector<int64_t>>(file, "/offsets");

    // (6,) int32, neighbor lists of all the nodes, one after the other.
    auto neighbors = H5Easy::load<std::vector<int64_t>>(file, "/neighbors");

    // (8,) int8, color of each node.
    auto colors = H5Easy::load<std::vector<int64_t>>(file, "/colors");

    // Number of nodes.
    auto n_nodes = H5Easy::loadAttribute<int64_t>(file, "/", "n_nodes");

    // Number of edges (entries of neighbors).
    auto n_edges = H5Easy::loadAttribute<int64_t>(file, "/", "n_edges");

    // The neighbors of node 0.
    if (offsets.size() > 1) {
        std::cout << "neighbors of node 0 ->";
        for (int64_t i = offsets[0]; i < offsets[1]; ++i) {
            std::cout << " " << neighbors[i];
        }
        std::cout << "\n";
    }

    // The shapes of what was loaded.
    std::cout << "offsets: " << offsets.size() << "\n";
    std::cout << "neighbors: " << neighbors.size() << "\n";
    std::cout << "colors: " << colors.size() << "\n";
    std::cout << "n_nodes: " << n_nodes << "\n";
    std::cout << "n_edges: " << n_edges << "\n";
}
